CREATE TABLE IF NOT EXISTS research (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT DEFAULT '', tags TEXT DEFAULT '[]', file_key TEXT NOT NULL, file_name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS posts (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, excerpt TEXT DEFAULT '', tags TEXT DEFAULT '[]', content TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, published_at TEXT);
CREATE TABLE IF NOT EXISTS podcast (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT DEFAULT '', episode TEXT DEFAULT '', file_key TEXT NOT NULL, file_name TEXT NOT NULL, created_at TEXT NOT NULL);
